contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable {
        require(dummy == 0, "dummy must be zero");
        address ownerBefore = c.smartfix_owner(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(address(this) != ownerBefore ? reverted : !reverted);
    }

    receive() external payable {}
}

